const frame = msg.payload || msg;
let canId = frame.canid;
const data = frame.data || [];

// Extended frame flag'i temizle (0x80000000)
canId = canId & 0x1FFFFFFF;

let state = flow.get("containerBattery") || {
    kind: "ContainerBatteryState",
    version: 1,
    totalVoltageV: null,
    currentA: null,
    cellTempC: null,
    socPercent: null,
    sohPercent: null,
    remainingEnergyKwh: null,
    availableEnergyKwh: null,
    cycleCount: null,
    state: null,
    stateCode: null,
    minCellVoltageMv: null,
    minCellBmuLoc: null,
    minCellCellLoc: null,
    maxCellVoltageMv: null,
    maxCellBmuLoc: null,
    maxCellCellLoc: null,
    avgCellVoltageMv: null,
    ambientTempC: null,
    alarms: {
        warning: false,
        danger: false,
        isolation: false,
        fuse: false,
        packOverCurrentWarning: false,
        packOverCurrentFault: false,
        dischargeContactorError: false,
        chargeContactorError: false,
        negContactorError: false,
        prechargeError: false,
        bmuError: false,
        emergencyStop: false,
        highHumidity: false,
        tempBalanceWarning: false,
        tempBalanceFault: false
    }
};

// Helper functions
function u16(buf, offset) {
    return (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
}

function s16(buf, offset) {
    var val = u16(buf, offset);
    return val > 0x7FFF ? val - 0x10000 : val;
}

function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function getBit(buf, byteOffset, bitOffset) {
    return (buf[byteOffset] >> bitOffset) & 0x01;
}

function getNibble(buf, byteOffset, highNibble) {
    if (highNibble) {
        return (buf[byteOffset] >> 4) & 0x0F;
    }
    return buf[byteOffset] & 0x0F;
}

// State code to string mapping
const stateMap = {
    0: "N/A",
    101: "Standby",
    102: "Startup",
    103: "Precharge",
    104: "Discharge",
    105: "Charge",
    106: "Shutdown",
    107: "Fault",
    108: "Charge_Complete",
    109: "Discharge_Complete"
};

var processed = false;

// BCU_01_Cell_Status (0x98F703F0 = 2566853104)
// Total Voltage, Current, Cell Temp
if (canId === 0x18F703F0 || canId === 0x98F703F0) {
    processed = true;
    state.totalVoltageV = u16(data, 0) * 0.1;
    state.currentA = (u16(data, 2) * 0.1) - 1000;
    state.cellTempC = u8(data, 7) - 40;
}

// BCU_01_Max_Min_Voltage_Status (0x98F704F0 = 2566853360)
// Min/Max Cell Voltage + Locations
if (canId === 0x18F704F0 || canId === 0x98F704F0) {
    processed = true;
    state.maxCellCellLoc = getNibble(data, 0, false);  // bits 0-3
    state.maxCellBmuLoc = getNibble(data, 0, true);    // bits 4-7
    state.minCellCellLoc = getNibble(data, 1, false);  // bits 8-11
    state.minCellBmuLoc = getNibble(data, 1, true);    // bits 12-15
    state.avgCellVoltageMv = u16(data, 2);             // bits 16-31
    state.maxCellVoltageMv = u16(data, 4);             // bits 32-47
    state.minCellVoltageMv = u16(data, 6);             // bits 48-63
}

// BCU_01_Battery_Status (0x98F706F0 = 2566853872)
// SOC, SOH, Remaining Energy, Cycles
if (canId === 0x18F706F0 || canId === 0x98F706F0) {
    processed = true;
    state.socPercent = u8(data, 0);                        // bits 0-7
    state.sohPercent = u8(data, 1);                        // bits 8-15
    state.cycleCount = u16(data, 2);                       // bits 16-31
    state.remainingEnergyKwh = u16(data, 4) * 0.01;        // bits 32-47
    state.availableEnergyKwh = u16(data, 6) * 0.01;        // bits 48-63
}

// BCU_01_Output_Status (0x98F705F0 = 2566852848)
// BCU State, Ambient Temp
if (canId === 0x18F705F0 || canId === 0x98F705F0) {
    processed = true;
    state.stateCode = u8(data, 0);
    state.state = stateMap[state.stateCode] || "Unknown";
    state.ambientTempC = u8(data, 3) - 40;
}

// BCU_01_Fault_Message (0x98F708F0 = 2566854384)
// Alarm flags
if (canId === 0x18F708F0 || canId === 0x98F708F0) {
    processed = true;
    // Byte 0
    state.alarms.warning = getBit(data, 0, 0) === 1;
    state.alarms.danger = getBit(data, 0, 1) === 1;
    // Byte 1
    state.alarms.packOverCurrentWarning = getBit(data, 1, 2) === 1;
    state.alarms.packOverCurrentFault = getBit(data, 1, 3) === 1;
    state.alarms.dischargeContactorError = getBit(data, 1, 5) === 1;
    state.alarms.chargeContactorError = getBit(data, 1, 6) === 1;
    state.alarms.fuse = getBit(data, 1, 7) === 1;
    // Byte 2
    state.alarms.highHumidity = getBit(data, 2, 3) === 1;
    state.alarms.bmuError = getBit(data, 2, 4) === 1;
    state.alarms.negContactorError = getBit(data, 2, 5) === 1;
    state.alarms.prechargeError = getBit(data, 2, 6) === 1;
    state.alarms.isolation = getBit(data, 2, 7) === 1;
    // Byte 3
    state.alarms.emergencyStop = getBit(data, 3, 0) === 1;
    state.alarms.tempBalanceWarning = getBit(data, 3, 1) === 1;
    state.alarms.tempBalanceFault = getBit(data, 3, 2) === 1;
}

if (!processed) {
    return null;
}

state.timestampUtc = new Date().toISOString();
flow.set("containerBattery", state);
msg.payload = state;
return msg;

var state = flow.get("containerBattery");
if (state) {
    msg.payload = state;
    return msg;
}
msg.payload = { error: "No data yet" };
return msg;
